"""Find the City With the Smallest Number of Neighbors — Floyd-Warshall.

n is small, so all-pairs shortest paths in O(n^3) is the simplest correct
approach; ties go to the largest index, which a >= comparison handles.

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        INF = float("inf")
        dist = [[0 if i == j else INF for j in range(n)] for i in range(n)]
        for u, v, w in edges:
            dist[u][v] = min(dist[u][v], w)
            dist[v][u] = min(dist[v][u], w)

        for k in range(n):
            for i in range(n):
                if dist[i][k] == INF:
                    continue
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        best_city, best_count = -1, n + 1
        for city in range(n):
            reachable = sum(1 for j in range(n)
                            if j != city and dist[city][j] <= distanceThreshold)
            if reachable <= best_count:
                best_city, best_count = city, reachable
        return best_city
